import { HEROES } from '../content/heroes.js';
import { dialogueFor } from '../content/dialogue.js';
const biographies = {
  'zhao-yun': '常山の剣士、趙雲。冷静な判断と揺るがぬ忠義で、戦火に追われる民を守る。青釭剣の精密な斬撃で気をため、龍の突撃で敵陣を破り、続く反撃を和らげる。',
  'lu-zhishen': '弱き者を見捨てぬ旅の僧、魯智深。豪放な心と鉄の禅杖で、不義を真正面から打ち砕く。山岳の鐘は体力を取り戻しながら敵を気絶させ、次の一撃への好機を生む。',
  'hu-sanniang': '滅びた屋敷の誇りを双刀に宿す、扈三娘。悲しみに屈せず、自らの正義を貫く。紅蓮の舞は素早い連撃で敵を追い詰め、戦いのさなかに失った力を取り戻す。',
  'lu-bu': '飛将の名で恐れられる呂布。方天画戟と比類なき自信を携え、幾千の敵にもひるまない。破天撃は守りを断ち切る圧倒的な一撃。慎重な駆け引きより、剛力で道を開く英雄。',
  'guan-yu': '義兄弟の誓いを胸に、青龍偃月刀を振るう関羽。威厳ある佇まいの奥に、民を守る固い決意を秘める。春秋一閃は大きな弧を描いて敵を斬り、反撃の勢いを削ぐ。',
  'wu-song': '景陽岡で虎を討った豪傑、武松。勇気と不屈の心を頼りに、虎狩りの棍を振るう。猛虎砕きは一人の敵を圧倒し、気絶させた隙に次の攻めを整える。',
  'mu-guiying': '卓越した采配と折れぬ意志を持つ女将、穆桂英。梨花槍は移り変わる敵の守りを的確に突く。梨花乱舞は攻撃、防御、回復を一つに結び、長く厳しい決闘を支える。',
  'liang-hongyu': '戦鼓で味方を奮い立たせる女傑、梁紅玉。双刀の一閃にも、兵を導く確かな拍子が宿る。戦鼓連斬は激しい連撃で敵を追い詰め、戦い続けるための力を取り戻す。',
  'nie-yinniang': '沈黙の中で育ちながら、自らの良心に従う刺客、聶隠娘。隠し短剣を手に、霧のように間合いへ忍び込む。影渡りは防御を抜けて深く斬り、退く際の反撃を軽減する。',
};
const warden = {
  'zhao-yun': ['常山の若き剣士か……門さえ顧みぬ帝国のために、なぜ血を流す？', '帝国のためではない。この門の向こうの民が、恐れず眠れるように戦う。刀を抜け。'],
  'lu-zhishen': ['数珠を血に染めた破戒僧。それがお前の慈悲か？', '仏は魂を救う。わしの禅杖は、お前のような悪鬼を救ってやるためにある！'],
  'hu-sanniang': ['扈家の生き残りか……茶畑に隠れていればよかったものを。', 'その旗には、まだ父の血が残っている。今日こそ、この双刀で洗い流す。'],
  'lu-bu': ['呂将軍！ 皇帝との盟約はどうした。なぜ味方の砦を襲う？！', 'この俺の道を塞いでおきながら、盟約を語るか。退け。さもなくば戟の下で裂けろ。'],
  'guan-yu': ['桃園の理想家か……農民のために兵を気取る、はぐれた神よ。', 'この刃を誓った相手は民だ。暴君ではない。日暮れまでに守将を討つ。'],
  'wu-song': ['景陽岡の虎殺し。己の噂に酔ったか……この関所は、組み伏せられる虎ではない。', '虎は素手で絞め倒した。お前は長柄を持っただけの人間だ。'],
  'mu-guiying': ['潰えた家の女将か……この門は、まだお前の家族を奪い足りぬようだ。', '家族は、このような門を開くために命を懸けた。私がその志を果たす。'],
  'liang-hongyu': ['川辺の戦鼓の女か……翠門関では、お前の太鼓も黙る。', '私の太鼓は、退却を告げたことがない。最期の拍子を聞け。お前のためのものだ。'],
  'nie-yinniang': ['霧から来た隠れ刃か……刺客に正々堂々たる戦の居場所はない。', '暴君を静かに葬る術を学んだ。だが今夜、霧は私に沈黙を求めてはいない。'],
};
const heron = {
  'zhao-yun': ['常山の旅人よ……浅瀬の波が足取りを語る。私の琴は、もうお前の間合いを知っている。', 'ならば青釭剣の音をよく聞け。張り巡らせた糸を、すべて断ち切る。'],
  'lu-zhishen': ['五台山の重い足音……力任せの怒りを調和と勘違いする、荒くれの僧か。', 'わしの禅杖に刺客の曲は要らぬ！ 好きなだけ弾け。その塔ごと打ち砕いてやる！'],
  'hu-sanniang': ['扈三娘……滅びた屋敷の娘よ。その双刀で川の悲しみから逃れられるとでも？', '一族が焼かれる間、お前の糸は闇で命を奪った。この水の上で、私の刃の復讐を聞け。'],
  'lu-bu': ['無敵の飛将が泥水を渡るとは……皇帝の調べにひざまずきに来たのか？', '籠の鳥の琴遊びか。最後の一音を弾け。この戟が塔を倒す前にな。'],
  'guan-yu': ['関羽……旗さえ恐れるその髭も、三尺の水に沈むのだ。', '川が増水しようと、刺客よ。青龍は沈まぬ。'],
  'wu-song': ['山の虎が水を渡るか……その咆哮も、雨にかき消される。', '虎はこの雨でも狩る。俺も同じだ。'],
  'mu-guiying': ['潰えた家の将よ……ここで指揮できるのは葦だけだ。', 'ならば葦を率いよう。お前の隠れ場所を囁いてくれる。'],
  'liang-hongyu': ['水を渡る戦鼓……その手から、ばちを切り落としてやろう。', '切るがいい。そのときは川そのものが、私の拍子を刻む。'],
  'nie-yinniang': ['影が影に出会ったか……お前も私も、同じ稼業だ。', '違う。お前は暴君に糸を売った。私の刃は、一度も売り物ではなかった。'],
};
const scenes = {
  arrival: ['灰旗軍が峠を押さえている。城壁の向こうでは、最後の避難民が山を越える道を待ち続けていた。', 'ならば、この門を開こう。'],
  'warden-fall': ['翠門関は、ただの入口にすぎぬ……皇帝はすでに都を歩いている。', '川の渡し場から煙が上がる。今宵、四人の刃は茶屋に身を寄せる。'],
  'bamboo-arrival': ['冷たい雨が竹の葉を打つ。浅瀬は深くなり、川霧の下では見えぬ刃がうごめいていた。', '浅瀬を越えよう。刺客ごときに、この旅は止められない。'],
  'heron-fall': ['弦は切れた……だが霧は晴れぬ。滄嵐山の高みを見よ……飛将が、お前たちを待つ。', '川の浅瀬に建つ塔は静まり返った。前には、滄嵐山の雲へと続く険しい道が待っている。'],
};
export const contentMessages = {'The road ahead': 'この先の道', 'Whispering Bamboo': '囁く竹林'};
for (const hero of HEROES) {
  contentMessages[hero.description] = biographies[hero.id];
  for (const [key, texts] of Object.entries({...scenes, 'warden-intro': warden[hero.id], 'heron-intro': heron[hero.id]}))
    if (texts) dialogueFor(key, hero).forEach((line, index) => {
      if (texts[index]) contentMessages[line.text] = texts[index];
    });
}
